'use client';

import { useState } from 'react';

import { cn } from '@/registry/ndeko/lib/utils';
import { Tabs, TabsList, TabsTab } from '@/registry/ndeko/ui/tabs';

import { CohortPanel } from './cohort-panel';
import { shadeOf, type Selection } from './cohort-model';
import { CohortTable } from './cohort-table';
import {
  COHORTS,
  DISPLAY_MODES,
  INITIAL_SELECTION,
  REPORT,
  type DisplayMode,
} from './data';

const REPORT_SURFACE =
  'bg-card hairline-ring ring-border rounded-xl shadow-[0_1px_2px_rgb(0_0_0/0.04)] dark:bg-foreground/[0.03]';

const LEGEND_STOPS = [0, 0.25, 0.5, 0.75, 1];

function isDisplayMode(value: unknown): value is DisplayMode {
  return DISPLAY_MODES.some((mode) => mode.id === value);
}

function cohortCountLabelOf(count: number) {
  if (count === 1) {
    return '1 weekly cohort';
  }
  return `${count} weekly cohorts`;
}

function ShadeLegend() {
  return (
    <div className='text-muted-foreground flex items-center gap-2 text-xs'>
      <span>0%</span>
      <span aria-hidden='true' className='flex gap-0.5'>
        {LEGEND_STOPS.map((stop) => (
          <span
            key={stop}
            style={{ backgroundColor: shadeOf(stop) }}
            className='hairline-ring ring-foreground/5 size-3 rounded-[3px]'
          />
        ))}
      </span>
      <span>100% still subscribed</span>
    </div>
  );
}

export default function Dashboards04() {
  const [mode, setMode] = useState<DisplayMode>('percent');
  const [selection, setSelection] = useState<Selection>(INITIAL_SELECTION);
  const cohortCount = cohortCountLabelOf(COHORTS.length);

  function pickMode(value: unknown) {
    if (isDisplayMode(value)) {
      setMode(value);
    }
  }

  return (
    <div className='bg-background text-foreground min-h-dvh w-full'>
      <div className='hairline-b border-border flex flex-wrap items-center gap-x-3 gap-y-2 px-4 py-3 md:px-6'>
        <div className='flex min-w-0 flex-wrap items-baseline gap-x-2 gap-y-0.5'>
          <h1 className='truncate text-lg font-semibold'>{REPORT.title}</h1>
          <span className='text-muted-foreground text-xs'>
            {REPORT.workspace} · {cohortCount}
          </span>
        </div>
        <div className='ms-auto'>
          <Tabs value={mode} onValueChange={pickMode}>
            <TabsList variant='segmented' aria-label='Show cells as'>
              {DISPLAY_MODES.map((option) => (
                <TabsTab key={option.id} value={option.id}>
                  {option.label}
                </TabsTab>
              ))}
            </TabsList>
          </Tabs>
        </div>
      </div>
      <div className='mx-auto grid w-full max-w-6xl gap-4 px-4 py-5 md:px-6 lg:grid-cols-[minmax(0,1fr)_17rem]'>
        <section
          aria-labelledby='dashboards-04-grid-title'
          className={cn(
            REPORT_SURFACE,
            'flex min-w-0 flex-col gap-3 p-3 sm:p-4'
          )}
        >
          <div className='flex flex-wrap items-baseline justify-between gap-x-3 gap-y-1 px-1'>
            <h2 id='dashboards-04-grid-title' className='text-sm font-medium'>
              Still subscribed, by sign-up week
            </h2>
            <span className='text-muted-foreground text-xs'>
              Illustrative figures
            </span>
          </div>
          <CohortTable
            mode={mode}
            selection={selection}
            onSelect={setSelection}
          />
          <div className='px-1'>
            <ShadeLegend />
          </div>
        </section>
        <section
          aria-label='Selected cohort'
          className={cn(REPORT_SURFACE, 'p-4')}
        >
          <CohortPanel selection={selection} />
        </section>
      </div>
    </div>
  );
}

'use client';

import {
  LayoutGroup,
  motion,
  type Transition,
  useReducedMotion,
} from 'motion/react';
import { useId, useRef } from 'react';

import { cn } from '@/registry/ndeko/lib/utils';

import {
  COHORT_ROWS,
  WEEK_AVERAGES,
  WEEKS,
  cellKeyOf,
  cellTextOf,
  formatCount,
  movedSelection,
  percentOf,
  sameSelection,
  shadeOf,
  weekLabelOf,
  type Cohort,
  type CohortCell,
  type Selection,
} from './cohort-model';
import type { DisplayMode } from './data';

const RING_TRAVEL: Transition = { type: 'spring', bounce: 0, duration: 0.3 };

const INSTANT: Transition = { duration: 0 };

const STICKY_HEADER =
  'bg-card dark:bg-[color-mix(in_oklab,var(--foreground)_3%,var(--background))] sticky start-0 z-10';

function ringTransitionOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return INSTANT;
  }
  return RING_TRAVEL;
}

function tabIndexOf(isSelected: boolean) {
  if (isSelected) {
    return 0;
  }
  return -1;
}

function cellLabelOf(cohort: Cohort, cell: CohortCell) {
  const week = weekLabelOf(cell.week);
  const percent = percentOf(cell.rate);
  const customers = formatCount(cell.retained);
  return `${cohort.label} cohort, ${week}: ${percent}% still subscribed, ${customers} customers`;
}

type CohortTableProps = {
  mode: DisplayMode;
  selection: Selection;
  onSelect: (selection: Selection) => void;
};

export function CohortTable({ mode, selection, onSelect }: CohortTableProps) {
  const layoutGroupId = useId();
  const tableRef = useRef<HTMLTableElement>(null);
  const shouldReduceMotion = useReducedMotion();
  const ringTransition = ringTransitionOf(shouldReduceMotion);

  function focusCell(next: Selection) {
    const key = cellKeyOf(next);
    const table = tableRef.current;
    const button = table?.querySelector<HTMLButtonElement>(
      `[data-cell="${key}"]`
    );
    button?.focus();
  }

  function handleKeyDown(event: React.KeyboardEvent<HTMLButtonElement>) {
    const next = movedSelection(selection, event.key);
    if (!next) {
      return;
    }
    event.preventDefault();
    if (sameSelection(next, selection)) {
      return;
    }
    onSelect(next);
    window.requestAnimationFrame(() => focusCell(next));
  }

  return (
    <motion.div layoutScroll className='-mx-1 overflow-x-auto px-1 pb-1'>
      <LayoutGroup id={layoutGroupId}>
        <table
          ref={tableRef}
          className='w-full min-w-[640px] border-separate border-spacing-1 text-xs tabular-nums'
        >
          <caption className='sr-only'>
            Share of each weekly sign-up cohort still subscribed, week by week.
            Use the arrow keys to move between weeks and cohorts.
          </caption>
          <thead>
            <tr className='text-muted-foreground'>
              <th
                scope='col'
                className={cn(STICKY_HEADER, 'h-8 pe-2 text-start font-normal')}
              >
                Cohort
              </th>
              <th scope='col' className='h-8 pe-2 text-end font-normal'>
                Customers
              </th>
              {WEEKS.map((week) => (
                <th key={week} scope='col' className='h-8 font-normal'>
                  {`W${week}`}
                  <span className='sr-only'>, {weekLabelOf(week)}</span>
                </th>
              ))}
            </tr>
          </thead>
          <tbody>
            {COHORT_ROWS.map((cohort, cohortIndex) => (
              <tr key={cohort.id}>
                <th
                  scope='row'
                  className={cn(STICKY_HEADER, 'pe-2 text-start font-medium')}
                >
                  {cohort.label}
                </th>
                <td className='text-muted-foreground pe-2 text-end'>
                  {formatCount(cohort.size)}
                </td>
                {WEEKS.map((week) => {
                  const cell = cohort.cells[week];
                  if (!cell) {
                    return (
                      <td key={week}>
                        <span
                          aria-hidden='true'
                          className='hairline-border border-foreground/15 block h-9 rounded-md border-dashed'
                        />
                        <span className='sr-only'>Not yet</span>
                      </td>
                    );
                  }
                  const here: Selection = { cohortIndex, week };
                  const isSelected = sameSelection(here, selection);
                  const shade = shadeOf(cell.rate);

                  return (
                    <td key={week}>
                      <button
                        type='button'
                        data-cell={cellKeyOf(here)}
                        tabIndex={tabIndexOf(isSelected)}
                        aria-pressed={isSelected}
                        aria-label={cellLabelOf(cohort, cell)}
                        onClick={() => onSelect(here)}
                        onKeyDown={handleKeyDown}
                        style={{ backgroundColor: shade }}
                        className='focus-visible:ring-ring/30 relative flex h-9 w-full min-w-12 cursor-pointer items-center justify-center rounded-md font-medium outline-none focus-visible:ring-[3px]'
                      >
                        {isSelected && (
                          <motion.span
                            layoutId='cohort-selection'
                            transition={ringTransition}
                            aria-hidden='true'
                            className='ring-foreground ring-offset-card pointer-events-none absolute inset-0 rounded-md ring-2 ring-offset-1'
                          />
                        )}
                        <span className='relative'>
                          {cellTextOf(mode, cell.rate, cell.retained)}
                        </span>
                      </button>
                    </td>
                  );
                })}
              </tr>
            ))}
          </tbody>
          <tfoot>
            <tr className='text-muted-foreground'>
              <th
                scope='row'
                className={cn(STICKY_HEADER, 'h-9 pe-2 text-start font-normal')}
              >
                Average
              </th>
              <td />
              {WEEK_AVERAGES.map((average) => (
                <td key={average.week} className='h-9 text-center'>
                  {cellTextOf(mode, average.rate, average.customers)}
                </td>
              ))}
            </tr>
          </tfoot>
        </table>
      </LayoutGroup>
    </motion.div>
  );
}

'use client';

import { AnimatePresence, motion, type Transition } from 'motion/react';

import { MotionNumber } from '@/components/core/motion-number';
import { cn } from '@/registry/ndeko/lib/utils';
import { Chip } from '@/registry/ndeko/ui/chip';

import {
  WEEK_AVERAGES,
  WEEKS,
  cellOf,
  formatCount,
  percentOf,
  weekLabelOf,
  type Cohort,
  type Selection,
} from './cohort-model';

const FADE_IN: Transition = { duration: 0.2, ease: [0.23, 1, 0.32, 1] };

const FADE_OUT: Transition = { duration: 0.12, ease: [0.23, 1, 0.32, 1] };

type Comparison = { label: string; color: string };

function comparisonOf(deltaPoints: number, week: number): Comparison {
  if (week === 0) {
    return {
      label: 'Every cohort starts at 100%',
      color: 'var(--muted-foreground)',
    };
  }
  const averageName = `the week ${week} average`;
  if (deltaPoints > 0) {
    return {
      label: `${deltaPoints} pts above ${averageName}`,
      color: 'var(--success)',
    };
  }
  if (deltaPoints < 0) {
    const gap = Math.abs(deltaPoints);
    return {
      label: `${gap} pts below ${averageName}`,
      color: 'var(--warning)',
    };
  }
  return {
    label: `Level with ${averageName}`,
    color: 'var(--muted-foreground)',
  };
}

function barToneOf(isSelected: boolean) {
  if (isSelected) {
    return 'bg-primary';
  }
  return 'bg-foreground/12';
}

function heightOf(rate: number) {
  const percent = rate * 100;
  return `${percent}%`;
}

type CohortCurveProps = {
  cohort: Cohort;
  selectedWeek: number;
};

/** The selected cohort week by week, each bar against the average of every cohort that reached that week. */
function CohortCurve({ cohort, selectedWeek }: CohortCurveProps) {
  return (
    <div className='flex flex-col gap-1.5'>
      <div aria-hidden='true' className='flex h-24 items-end gap-1.5'>
        {WEEKS.map((week) => {
          const cell = cohort.cells[week];
          const average = WEEK_AVERAGES[week];
          if (!cell) {
            return (
              <span
                key={week}
                className='hairline-border border-foreground/15 h-2 flex-1 rounded-[3px] border-dashed'
              />
            );
          }
          const isSelected = week === selectedWeek;

          return (
            <span key={week} className='relative h-full flex-1'>
              <span
                style={{ height: heightOf(cell.rate) }}
                className={cn(
                  'absolute inset-x-0 bottom-0 rounded-[3px] transition-colors duration-150',
                  barToneOf(isSelected)
                )}
              />
              <span
                style={{ bottom: heightOf(average.rate) }}
                className='bg-foreground/60 absolute -inset-x-0.5 h-0.5 rounded-full'
              />
            </span>
          );
        })}
      </div>
      <div
        aria-hidden='true'
        className='text-muted-foreground flex gap-1.5 text-[11px] tabular-nums'
      >
        {WEEKS.map((week) => (
          <span key={week} className='flex-1 text-center'>
            {`W${week}`}
          </span>
        ))}
      </div>
    </div>
  );
}

export function CohortPanel({ selection }: { selection: Selection }) {
  const { cohort, cell } = cellOf(selection);
  const average = WEEK_AVERAGES[selection.week];
  const percent = percentOf(cell.rate);
  const averagePercent = percentOf(average.rate);
  const deltaPoints = percent - averagePercent;
  const comparison = comparisonOf(deltaPoints, selection.week);
  const weekLabel = weekLabelOf(selection.week);
  const retained = formatCount(cell.retained);
  const size = formatCount(cohort.size);
  const curveKey = cohort.id;

  return (
    <div className='flex flex-col gap-5'>
      <div className='flex flex-col gap-1'>
        <p className='text-muted-foreground text-xs'>
          {cohort.label} cohort · {weekLabel}
        </p>
        <MotionNumber
          value={percent}
          suffix='%'
          className='text-3xl leading-9 font-semibold'
        />
        <p className='text-muted-foreground text-[13px] text-pretty'>
          {retained} of {size} customers still subscribed
        </p>
      </div>
      <Chip color={comparison.color} className='h-6 px-2 text-xs'>
        {comparison.label}
      </Chip>
      <div className='flex flex-col gap-2'>
        <p className='text-xs font-medium'>{cohort.label} week by week</p>
        <div className='relative'>
          <AnimatePresence mode='popLayout' initial={false}>
            <motion.div
              key={curveKey}
              initial={{ opacity: 0 }}
              animate={{ opacity: 1, transition: FADE_IN }}
              exit={{ opacity: 0, transition: FADE_OUT }}
            >
              <CohortCurve cohort={cohort} selectedWeek={selection.week} />
            </motion.div>
          </AnimatePresence>
        </div>
        <p className='text-muted-foreground text-xs text-pretty'>
          Bars are this cohort, the line on each is the average of every cohort
        </p>
      </div>
    </div>
  );
}

import {
  BASE_CURVE,
  COHORTS,
  WEEK_COUNT,
  type CohortSeed,
  type DisplayMode,
} from './data';

export type CohortCell = {
  week: number;
  retained: number;
  rate: number;
};

export type Cohort = CohortSeed & { cells: CohortCell[] };

export type WeekAverage = {
  week: number;
  rate: number;
  customers: number;
};

export type Selection = {
  cohortIndex: number;
  week: number;
};

const COUNT_FORMAT = new Intl.NumberFormat('en-US');

const SHADE_FLOOR = 6;

const SHADE_RANGE = 64;

export const WEEKS = Array.from({ length: WEEK_COUNT }, (_, week) => week);

/** Later cohorts keep a little more, and each week wobbles a point or two, so the grid reads like real data. */
function driftOf(cohortIndex: number, week: number) {
  const lift = cohortIndex * 0.012;
  const seed = (cohortIndex * 7 + week * 13) % 9;
  const wobble = (seed - 4) / 250;
  return lift + wobble;
}

function clampRate(rate: number) {
  const atMost = Math.min(rate, 1);
  return Math.max(atMost, 0);
}

function rateOf(cohortIndex: number, week: number) {
  if (week === 0) {
    return 1;
  }
  const drift = driftOf(cohortIndex, week);
  const drifted = BASE_CURVE[week] + drift;
  return clampRate(drifted);
}

export function weeksAvailableOf(cohortIndex: number) {
  return WEEK_COUNT - cohortIndex;
}

function cellsOf(seed: CohortSeed, cohortIndex: number) {
  const available = weeksAvailableOf(cohortIndex);
  const weeks = WEEKS.slice(0, available);
  return weeks.map((week) => {
    const rate = rateOf(cohortIndex, week);
    const retained = Math.round(seed.size * rate);
    const cell: CohortCell = { week, retained, rate: retained / seed.size };
    return cell;
  });
}

export const COHORT_ROWS: Cohort[] = COHORTS.map((seed, cohortIndex) => ({
  ...seed,
  cells: cellsOf(seed, cohortIndex),
}));

function averageOf(week: number): WeekAverage {
  let retained = 0;
  let size = 0;
  let cohortCount = 0;
  for (const cohort of COHORT_ROWS) {
    const cell = cohort.cells[week];
    if (cell) {
      retained += cell.retained;
      size += cohort.size;
      cohortCount += 1;
    }
  }
  return {
    week,
    rate: retained / size,
    customers: Math.round(retained / cohortCount),
  };
}

export const WEEK_AVERAGES: WeekAverage[] = WEEKS.map(averageOf);

export function formatCount(value: number) {
  return COUNT_FORMAT.format(value);
}

export function percentOf(rate: number) {
  return Math.round(rate * 100);
}

export function cellTextOf(mode: DisplayMode, rate: number, customers: number) {
  if (mode === 'customers') {
    return formatCount(customers);
  }
  return `${percentOf(rate)}%`;
}

/** One hue, deeper as more of the cohort stays. Capped so the label keeps its contrast in both themes. */
export function shadeOf(rate: number) {
  const mix = SHADE_FLOOR + rate * SHADE_RANGE;
  const rounded = Math.round(mix);
  return `color-mix(in oklab, var(--primary) ${rounded}%, transparent)`;
}

export function weekLabelOf(week: number) {
  if (week === 0) {
    return 'Sign-up week';
  }
  return `Week ${week}`;
}

export function cellOf(selection: Selection) {
  const cohort = COHORT_ROWS[selection.cohortIndex];
  const cell = cohort.cells[selection.week];
  return { cohort, cell };
}

function clampWeek(cohortIndex: number, week: number) {
  const lastWeek = weeksAvailableOf(cohortIndex) - 1;
  const atMost = Math.min(week, lastWeek);
  return Math.max(atMost, 0);
}

function clampCohort(cohortIndex: number) {
  const lastCohort = COHORT_ROWS.length - 1;
  const atMost = Math.min(cohortIndex, lastCohort);
  return Math.max(atMost, 0);
}

function rawTargetOf(selection: Selection, key: string): Selection | null {
  const { cohortIndex, week } = selection;
  if (key === 'ArrowRight') {
    return { cohortIndex, week: week + 1 };
  }
  if (key === 'ArrowLeft') {
    return { cohortIndex, week: week - 1 };
  }
  if (key === 'Home') {
    return { cohortIndex, week: 0 };
  }
  if (key === 'End') {
    return { cohortIndex, week: WEEK_COUNT };
  }
  if (key === 'ArrowDown') {
    return { cohortIndex: cohortIndex + 1, week };
  }
  if (key === 'ArrowUp') {
    return { cohortIndex: cohortIndex - 1, week };
  }
  return null;
}

/** Moves the selection the way the key points, staying on weeks that already happened. */
export function movedSelection(selection: Selection, key: string) {
  const target = rawTargetOf(selection, key);
  if (!target) {
    return null;
  }
  const cohortIndex = clampCohort(target.cohortIndex);
  const week = clampWeek(cohortIndex, target.week);
  const moved: Selection = { cohortIndex, week };
  return moved;
}

export function sameSelection(first: Selection, second: Selection) {
  const sameCohort = first.cohortIndex === second.cohortIndex;
  const sameWeek = first.week === second.week;
  return sameCohort && sameWeek;
}

export function cellKeyOf(selection: Selection) {
  return `${selection.cohortIndex}-${selection.week}`;
}

export type DisplayMode = 'percent' | 'customers';

export type CohortSeed = {
  id: string;
  /** The Monday the cohort signed up. */
  label: string;
  size: number;
};

export const REPORT = {
  title: 'Retention',
  workspace: 'Tidepool Coffee subscriptions',
};

export const WEEK_COUNT = 8;

export const DISPLAY_MODES: { id: DisplayMode; label: string }[] = [
  { id: 'percent', label: 'Percent' },
  { id: 'customers', label: 'Customers' },
];

/** Share of a cohort still subscribed after each week, before each cohort's own drift. */
export const BASE_CURVE = [1, 0.64, 0.53, 0.47, 0.43, 0.4, 0.38, 0.37];

export const COHORTS: CohortSeed[] = [
  { id: 'sep-01', label: 'Sep 1', size: 1180 },
  { id: 'sep-08', label: 'Sep 8', size: 1242 },
  { id: 'sep-15', label: 'Sep 15', size: 1096 },
  { id: 'sep-22', label: 'Sep 22', size: 1320 },
  { id: 'sep-29', label: 'Sep 29', size: 1275 },
  { id: 'oct-06', label: 'Oct 6', size: 1408 },
  { id: 'oct-13', label: 'Oct 13', size: 1361 },
  { id: 'oct-20', label: 'Oct 20', size: 1452 },
];

export const INITIAL_SELECTION = { cohortIndex: 2, week: 3 };
